if __name__ == "__main__":
    import json
    import re
    from pathlib import Path

    here = Path(__file__).resolve().parent
    norm = lambda s: re.sub(r"\s+", " ", s).strip()
    dico = {}
    for fr, en in PAIRES:
        cle = norm(fr)
        if cle in dico and dico[cle] != en:
            print("Doublon avec traductions différentes :", cle[:60])
        dico[cle] = en
    # Légendes de la frise de l'accueil, écrites par scripts/build-couverture.py
    frise_en = here / "frise_en.json"
    if frise_en.exists():
        for fr, en in json.loads(frise_en.read_text(encoding="utf-8")).items():
            dico.setdefault(norm(fr), en)
    (here / "en.json").write_text(json.dumps(dico, ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")

    # Contrôle : clés qui ne correspondent à aucun texte attendu (coquille probable)
    attendus_path = here / "a-traduire.json"
    if attendus_path.exists():
        attendus = set(json.loads(attendus_path.read_text(encoding="utf-8")))
        if attendus:
            inconnues = [k for k in dico if k not in attendus]
            print(f"{len(dico)} traductions écrites dans i18n/en.json")
            print(f"{len(attendus - set(dico))} texte(s) encore sans traduction")
            if inconnues:
                print(f"{len(inconnues)} clé(s) qui ne correspondent à aucun texte manquant (déjà traduites ou coquilles) :")
                for k in inconnues[:20]:
                    print("   -", k[:90])
